const revokePolicyExceptionGroupMembers = `-- name: RevokePolicyExceptionGroupMembers :many
UPDATE pc.policy_exceptions SET state = 'REVOKED', revoked_by = $1, revoked_reason = $2
WHERE org_id = $3 AND group_id = $4::uuid AND state IN ('PENDING', 'ACTIVE')
  AND coalesce(expires_at, requested_expiry) > now()
RETURNING org_id, id, bundle_id, rule_id, rule_digest, agent_id, operations, reason, owner_id, requested_by, requested_expiry, state, activated_at, expires_at, revoked_by, revoked_reason, created_at, group_id
`

type RevokePolicyExceptionGroupMembersParams struct {
	RevokedBy     *ids.UUID
	RevokedReason *string
	OrgID         ids.OrgID
	GroupID       ids.UUID
}

// Revoking a group revokes each of its open member rows.
func (q *Queries) RevokePolicyExceptionGroupMembers(ctx context.Context, arg RevokePolicyExceptionGroupMembersParams) ([]PcPolicyException, error) {
	rows, err := q.db.Query(ctx, revokePolicyExceptionGroupMembers,
		arg.RevokedBy,
		arg.RevokedReason,
		arg.OrgID,
		arg.GroupID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PcPolicyException{}
	for rows.Next() {
		var i PcPolicyException
		if err := rows.Scan(
			&i.OrgID,
			&i.ID,
			&i.BundleID,
			&i.RuleID,
			&i.RuleDigest,
			&i.AgentID,
			&i.Operations,
			&i.Reason,
			&i.OwnerID,
			&i.RequestedBy,
			&i.RequestedExpiry,
			&i.State,
			&i.ActivatedAt,
			&i.ExpiresAt,
			&i.RevokedBy,
			&i.RevokedReason,
			&i.CreatedAt,
			&i.GroupID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
